-- Fovyn V1.8: gym equipment, availability, template preferences and substitutions.
create table if not exists public.training_gym_equipment(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,gym_id uuid not null references public.training_gym_profiles(id) on delete cascade,name text not null,notes text,photo_url text,preferred boolean not null default false,archived_at timestamptz,created_at timestamptz not null default now(),unique(gym_id,name));
create table if not exists public.training_gym_exercises(owner_id uuid not null references auth.users(id) on delete cascade,gym_id uuid not null references public.training_gym_profiles(id) on delete cascade,exercise_id uuid not null references public.training_exercises(id) on delete cascade,equipment_id uuid references public.training_gym_equipment(id) on delete set null,is_available boolean not null default true,is_preferred boolean not null default false,notes text,updated_at timestamptz not null default now(),primary key(gym_id,exercise_id));
create table if not exists public.training_gym_template_preferences(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,gym_id uuid not null references public.training_gym_profiles(id) on delete cascade,template_id uuid not null references public.training_templates(id) on delete cascade,template_slot_id uuid not null references public.training_template_slots(id) on delete cascade,exercise_id uuid not null references public.training_exercises(id) on delete cascade,updated_at timestamptz not null default now(),unique(gym_id,template_slot_id));
create table if not exists public.training_workout_substitutions(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,session_id uuid references public.training_sessions(id) on delete cascade,gym_id uuid references public.training_gym_profiles(id) on delete set null,template_slot_id uuid references public.training_template_slots(id) on delete set null,original_exercise_id uuid not null references public.training_exercises(id),replacement_exercise_id uuid not null references public.training_exercises(id),scope text not null default 'session' check(scope in ('session','gym_preference')),created_at timestamptz not null default now());
alter table public.training_sessions add column if not exists gym_id uuid references public.training_gym_profiles(id) on delete set null;
alter table public.training_session_exercises add column if not exists original_exercise_id uuid references public.training_exercises(id) on delete set null;
alter table public.training_session_exercises add column if not exists substitution_source text check(substitution_source is null or substitution_source in ('session','gym_preference'));
alter table public.training_gym_equipment enable row level security;alter table public.training_gym_exercises enable row level security;alter table public.training_gym_template_preferences enable row level security;alter table public.training_workout_substitutions enable row level security;
create policy training_gym_equipment_owner_all on public.training_gym_equipment for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy training_gym_exercises_owner_all on public.training_gym_exercises for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy training_gym_template_preferences_owner_all on public.training_gym_template_preferences for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy training_workout_substitutions_owner_all on public.training_workout_substitutions for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());